{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "DropdownMenuGroup",
    "subComponentOf": "DropdownMenu",
    "displayName": "Dropdown Menu Group",
    "isHiddenFromOverview": true,
    "playground": {
      "defaults": {
        "title": "Version history"
      }
    },
    "description": "A group of rows in a compound menu. A visible title names role=\"group\" through aria-labelledby; an omitted title leaves the group unnamed. The heading is not a menuitem, so arrow keys and typeahead skip it. Keep title content non-interactive and place controls in DropdownMenu header or footer. The data-driven equivalent is the `{type: \"section\", title, items}` entry in `items`; both forms share the heading treatment and theme target. Host attributes and DOM handlers (id, data-*, aria-*) reach the group element; its role, and its name while it has a title, stay component-owned.",
    "usage": {
      "description": "Use DropdownMenuGroup to give related compound-menu rows one visible and programmatic name. Use an untitled group only when a separate name would not help people understand the rows.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use short, descriptive title content that explains what the grouped rows have in common."
        },
        {
          "guidance": true,
          "description": "Keep the title non-interactive so every available action remains in the menu arrow-key order."
        },
        {
          "guidance": false,
          "description": "Place buttons, links, fields, or other controls in title. Put them in DropdownMenu header or footer instead."
        },
        {
          "guidance": false,
          "description": "Wrap rows that do not form a meaningful set; a group adds structure only when its relationship helps users."
        }
      ],
      "anatomy": [
        {
          "name": "Group",
          "required": true,
          "description": "The role=\"group\" wrapper containing the heading and menu rows."
        },
        {
          "name": "Heading",
          "required": false,
          "description": "Visible non-interactive title content that names the group and carries the dropdown-menu-section-heading theme target."
        },
        {
          "name": "Rows",
          "required": false,
          "description": "Menu items, selectable items, radio groups, or submenus owned by DropdownMenu."
        }
      ]
    },
    "props": [
      {
        "name": "title",
        "type": "ReactNode",
        "description": "Non-interactive heading content shown above the rows and used as the group's accessible name. Omit for an unnamed group; place controls in DropdownMenu header or footer."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "The grouped rows: DropdownMenuItem, DropdownMenuCheckboxItem, DropdownMenuRadioGroup, or DropdownMenuSubMenu."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles applied to the role=\"group\" wrapper. Must be a stylex.create() value, not an inline style object."
      },
      {
        "name": "className",
        "type": "string",
        "description": "CSS class name applied to the role=\"group\" wrapper."
      },
      {
        "name": "style",
        "type": "React.CSSProperties",
        "description": "Inline styles applied to the role=\"group\" wrapper."
      },
      {
        "name": "ref",
        "type": "React.Ref<HTMLDivElement>",
        "description": "Ref forwarded to the role=\"group\" wrapper."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-dropdown-menu-section-heading"
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/DropdownMenu",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
